func TestResolveModel(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name     string
		provider string
		model    string
		want     string
	}{
		{
			name:     "claude code with empty model defaults to DefaultModel",
			provider: string(agent.AgentNameClaudeCode),
			model:    "",
			want:     DefaultModel,
		},
		{
			name:     "claude code with explicit model is unchanged",
			provider: string(agent.AgentNameClaudeCode),
			model:    "opus",
			want:     "opus",
		},
		{
			name:     "other provider with empty model stays empty",
			provider: "gemini",
			model:    "",
			want:     "",
		},
		{
			name:     "other provider with explicit model is unchanged",
			provider: "codex",
			model:    "gpt-5",
			want:     "gpt-5",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got := ResolveModel(agent.AgentName(tt.provider), tt.model)
			if got != tt.want {
				t.Errorf("ResolveModel(%q, %q) = %q, want %q", tt.provider, tt.model, got, tt.want)
			}
		})
	}
}

